// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for string_get_size() from lib/string_helpers.c.
 */
#include <kunit/test.h>
#include <linux/limits.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define AGENT_BUF_LEN	32

/*
 * Format @size blocks of @blk_size with @units into a fresh buffer and check
 * both the produced string and the returned length (which must equal the
 * length of the string when nothing was truncated).
 */
static void agent_check(struct kunit *test, u64 size, u64 blk_size,
			enum string_size_units units, const char *exp)
{
	char buf[AGENT_BUF_LEN];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(size, blk_size, units, buf, sizeof(buf));

	KUNIT_EXPECT_STREQ_MSG(test, buf, exp,
			       "string_get_size(%llu, %llu, 0x%x)",
			       size, blk_size, (unsigned int)units);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(exp),
			    "return value for string_get_size(%llu, %llu, 0x%x)",
			    size, blk_size, (unsigned int)units);
}

/* Check both unit bases at once. */
static void agent_check_both(struct kunit *test, u64 size, u64 blk_size,
			     const char *exp10, const char *exp2)
{
	agent_check(test, size, blk_size, STRING_UNITS_10, exp10);
	agent_check(test, size, blk_size, STRING_UNITS_2, exp2);
}

/* ---- zero handling ------------------------------------------------- */

static void agent_test_zero(struct kunit *test)
{
	/* zero size */
	agent_check_both(test, 0, 1, "0 B", "0 B");
	agent_check_both(test, 0, 512, "0 B", "0 B");
	agent_check_both(test, 0, U64_MAX, "0 B", "0 B");
	/* zero block size forces a zero result regardless of size */
	agent_check_both(test, 1, 0, "0 B", "0 B");
	agent_check_both(test, 123456789, 0, "0 B", "0 B");
	agent_check_both(test, U64_MAX, 0, "0 B", "0 B");
	agent_check_both(test, 0, 0, "0 B", "0 B");
}

static void agent_test_zero_flags(struct kunit *test)
{
	agent_check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
	agent_check(test, 0, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE, "0B");
	agent_check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "0 ");
	agent_check(test, 0, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "0 ");
	agent_check(test, 7, 0,
		    STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		    "0");
	agent_check(test, 7, 0,
		    STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		    "0");
}

/* ---- plain bytes, below the first unit ----------------------------- */

static void agent_test_bytes(struct kunit *test)
{
	/* single digit values get two decimals */
	agent_check_both(test, 1, 1, "1.00 B", "1.00 B");
	agent_check_both(test, 9, 1, "9.00 B", "9.00 B");
	/* two digit values get one decimal */
	agent_check_both(test, 10, 1, "10.0 B", "10.0 B");
	agent_check_both(test, 99, 1, "99.0 B", "99.0 B");
	/* three digit values get none */
	agent_check_both(test, 100, 1, "100 B", "100 B");
	agent_check_both(test, 512, 1, "512 B", "512 B");
	agent_check_both(test, 999, 1, "999 B", "999 B");
	/* blocks still below any unit */
	agent_check_both(test, 1, 512, "512 B", "512 B");
	agent_check_both(test, 3, 333, "999 B", "999 B");
}

/* ---- divisor boundaries (999/1000 and 1023/1024) ------------------- */

static void agent_test_divisor_boundary(struct kunit *test)
{
	/* exactly 1000: a unit in SI, still bytes in binary */
	agent_check_both(test, 1000, 1, "1.00 kB", "1000 B");
	agent_check_both(test, 1001, 1, "1.00 kB", "1001 B");
	/* 1023/1024: the binary edge */
	agent_check_both(test, 1023, 1, "1.02 kB", "1023 B");
	agent_check_both(test, 1024, 1, "1.02 kB", "1.00 KiB");
	agent_check_both(test, 1025, 1, "1.03 kB", "1.00 KiB");
	/* same edge reached through block size */
	agent_check_both(test, 2, 512, "1.02 kB", "1.00 KiB");
	agent_check_both(test, 1, 1024, "1.02 kB", "1.00 KiB");
	agent_check_both(test, 4, 250, "1.00 kB", "1000 B");
	/* second unit edge */
	agent_check_both(test, 999999, 1, "1000 kB", "977 KiB");
	agent_check_both(test, 1000000, 1, "1.00 MB", "977 KiB");
	/* 1048575 = 1023 KiB + 1023 B rounds to 1024 KiB, not 1.00 MiB */
	agent_check_both(test, 1048575, 1, "1.05 MB", "1024 KiB");
	agent_check_both(test, 1048576, 1, "1.05 MB", "1.00 MiB");
}

/* ---- number of significant decimals (j selection) ------------------ */

static void agent_test_precision_digits(struct kunit *test)
{
	/* SI: 9 -> two decimals, 10 -> one decimal, 100 -> none */
	agent_check(test, 9000, 1, STRING_UNITS_10, "9.00 kB");
	/* precision is chosen before the round-up carry: 9.999 -> "10.00" */
	agent_check(test, 9999, 1, STRING_UNITS_10, "10.00 kB");
	agent_check(test, 10000, 1, STRING_UNITS_10, "10.0 kB");
	agent_check(test, 99000, 1, STRING_UNITS_10, "99.0 kB");
	agent_check(test, 99999, 1, STRING_UNITS_10, "100.0 kB");
	agent_check(test, 100000, 1, STRING_UNITS_10, "100 kB");
	agent_check(test, 999000, 1, STRING_UNITS_10, "999 kB");

	/* binary equivalents */
	agent_check(test, 9 * 1024, 1, STRING_UNITS_2, "9.00 KiB");
	agent_check(test, 10 * 1024, 1, STRING_UNITS_2, "10.0 KiB");
	agent_check(test, 99 * 1024, 1, STRING_UNITS_2, "99.0 KiB");
	agent_check(test, 100 * 1024, 1, STRING_UNITS_2, "100 KiB");
	agent_check(test, 1023 * 1024, 1, STRING_UNITS_2, "1023 KiB");
}

/* ---- rounding of the dropped digit --------------------------------- */

static void agent_test_rounding_si(struct kunit *test)
{
	/* two decimals: 1.004 stays 1.00, 1.005 becomes 1.01 */
	agent_check(test, 1004, 1, STRING_UNITS_10, "1.00 kB");
	agent_check(test, 1005, 1, STRING_UNITS_10, "1.01 kB");
	agent_check(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	agent_check(test, 1995, 1, STRING_UNITS_10, "2.00 kB");
	agent_check(test, 1999, 1, STRING_UNITS_10, "2.00 kB");
	/* one decimal: 10.049 stays 10.0, 10.050 becomes 10.1 */
	agent_check(test, 10049, 1, STRING_UNITS_10, "10.0 kB");
	agent_check(test, 10050, 1, STRING_UNITS_10, "10.1 kB");
	agent_check(test, 99949, 1, STRING_UNITS_10, "99.9 kB");
	agent_check(test, 99950, 1, STRING_UNITS_10, "100.0 kB");
	/* no decimals: 100.499 stays 100, 100.500 becomes 101 */
	agent_check(test, 100499, 1, STRING_UNITS_10, "100 kB");
	agent_check(test, 100500, 1, STRING_UNITS_10, "101 kB");
	agent_check(test, 999499, 1, STRING_UNITS_10, "999 kB");
	agent_check(test, 999500, 1, STRING_UNITS_10, "1000 kB");
	/* carry across the unit boundary happens only on the next unit */
	agent_check(test, 1100, 1, STRING_UNITS_10, "1.10 kB");
	agent_check(test, 1536, 1, STRING_UNITS_10, "1.54 kB");
}

static void agent_test_rounding_binary(struct kunit *test)
{
	/* 1.5 KiB exactly */
	agent_check(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	/* 1100 B = 1.07421875 KiB */
	agent_check(test, 1100, 1, STRING_UNITS_2, "1.07 KiB");
	/* 1999 B = 1.952 KiB */
	agent_check(test, 1999, 1, STRING_UNITS_2, "1.95 KiB");
	/* 2047 B = 1.999 KiB rounds up with carry */
	agent_check(test, 2047, 1, STRING_UNITS_2, "2.00 KiB");
	agent_check(test, 2048, 1, STRING_UNITS_2, "2.00 KiB");
	/* 10000 B = 9.765625 KiB */
	agent_check(test, 10000, 1, STRING_UNITS_2, "9.77 KiB");
	/* 99999 B = 97.655 KiB */
	agent_check(test, 99999, 1, STRING_UNITS_2, "97.7 KiB");
	/* 1000000 B = 976.5625 KiB -> 977 */
	agent_check(test, 1000000, 1, STRING_UNITS_2, "977 KiB");
	/* remainder 1023/1024 with no decimals printed */
	agent_check(test, 1023 * 1024 + 1023, 1, STRING_UNITS_2, "1024 KiB");
	/* remainder of exactly 512 (0.5) with no decimals rounds up */
	agent_check(test, 100 * 1024 + 512, 1, STRING_UNITS_2, "101 KiB");
	agent_check(test, 100 * 1024 + 511, 1, STRING_UNITS_2, "100 KiB");
}

/* ---- block size interaction ---------------------------------------- */

static void agent_test_block_size(struct kunit *test)
{
	agent_check_both(test, 2048, 512, "1.05 MB", "1.00 MiB");
	agent_check_both(test, 16384, 512, "8.39 MB", "8.00 MiB");
	agent_check_both(test, 8192, 4096, "33.6 MB", "32.0 MiB");
	agent_check_both(test, 3000, 1900, "5.70 MB", "5.44 MiB");
	agent_check_both(test, 500118192, 512, "256 GB", "238 GiB");
	agent_check_both(test, 1, 1000000, "1.00 MB", "977 KiB");
	agent_check_both(test, 1000000, 1000000, "1.00 TB", "931 GiB");
	/* size and block size are interchangeable */
	agent_check_both(test, 512, 2048, "1.05 MB", "1.00 MiB");
	agent_check_both(test, 1900, 3000, "5.70 MB", "5.44 MiB");
}

/* ---- every unit suffix in both bases ------------------------------- */

static void agent_test_all_units_binary(struct kunit *test)
{
	agent_check(test, 1, 1ULL << 0, STRING_UNITS_2, "1.00 B");
	agent_check(test, 1, 1ULL << 10, STRING_UNITS_2, "1.00 KiB");
	agent_check(test, 1, 1ULL << 20, STRING_UNITS_2, "1.00 MiB");
	agent_check(test, 1, 1ULL << 30, STRING_UNITS_2, "1.00 GiB");
	agent_check(test, 1, 1ULL << 40, STRING_UNITS_2, "1.00 TiB");
	agent_check(test, 1, 1ULL << 50, STRING_UNITS_2, "1.00 PiB");
	agent_check(test, 1, 1ULL << 60, STRING_UNITS_2, "1.00 EiB");
	agent_check(test, 1ULL << 40, 1ULL << 30, STRING_UNITS_2, "1.00 ZiB");
	agent_check(test, 1ULL << 40, 1ULL << 40, STRING_UNITS_2, "1.00 YiB");
	/* same through the size argument */
	agent_check(test, 1ULL << 50, 1, STRING_UNITS_2, "1.00 PiB");
	agent_check(test, 1ULL << 63, 1, STRING_UNITS_2, "8.00 EiB");
}

static void agent_test_all_units_si(struct kunit *test)
{
	agent_check(test, 1, 1ULL, STRING_UNITS_10, "1.00 B");
	agent_check(test, 1, 1000ULL, STRING_UNITS_10, "1.00 kB");
	agent_check(test, 1, 1000000ULL, STRING_UNITS_10, "1.00 MB");
	agent_check(test, 1, 1000000000ULL, STRING_UNITS_10, "1.00 GB");
	agent_check(test, 1, 1000000000000ULL, STRING_UNITS_10, "1.00 TB");
	agent_check(test, 1, 1000000000000000ULL, STRING_UNITS_10, "1.00 PB");
	agent_check(test, 1, 1000000000000000000ULL, STRING_UNITS_10, "1.00 EB");
	agent_check(test, 1000, 1000000000000000000ULL, STRING_UNITS_10, "1.00 ZB");
	agent_check(test, 1000000, 1000000000000000000ULL, STRING_UNITS_10,
		    "1.00 YB");
	/* binary powers expressed in SI units */
	agent_check(test, 1, 1ULL << 40, STRING_UNITS_10, "1.10 TB");
	agent_check(test, 1ULL << 40, 1ULL << 30, STRING_UNITS_10, "1.18 ZB");
	agent_check(test, 1ULL << 40, 1ULL << 40, STRING_UNITS_10, "1.21 YB");
}

/* ---- the 32-bit pre-reduction of large operands -------------------- */

static void agent_test_large_operands(struct kunit *test)
{
	/* just below and at the 2^32 pre-reduction threshold */
	agent_check_both(test, 0xffffffffULL, 1, "4.29 GB", "4.00 GiB");
	agent_check_both(test, 0x100000000ULL, 1, "4.29 GB", "4.00 GiB");
	agent_check_both(test, 1, 0xffffffffULL, "4.29 GB", "4.00 GiB");
	agent_check_both(test, 1, 0x100000000ULL, "4.29 GB", "4.00 GiB");
	/* both operands above 2^32 */
	agent_check_both(test, 0x100000000ULL, 0x100000000ULL,
			 "18.4 EB", "16.0 EiB");
	/* U64_MAX as either operand (from the upstream reference values) */
	agent_check_both(test, U64_MAX, 4096, "75.6 ZB", "64.0 ZiB");
	agent_check_both(test, 4096, U64_MAX, "75.6 ZB", "64.0 ZiB");
	agent_check_both(test, U64_MAX, 1, "18.4 EB", "16.0 EiB");
}

/* ---- overflow past the last known unit ----------------------------- */

static void agent_test_unknown_unit(struct kunit *test)
{
	char buf[AGENT_BUF_LEN];
	int ret;

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));
	KUNIT_EXPECT_NOT_NULL(test, strstr(buf, " UNKB"));
	KUNIT_EXPECT_NULL(test, strstr(buf, "Yi"));

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));
	KUNIT_EXPECT_NOT_NULL(test, strstr(buf, " UNKB"));

	ret = string_get_size(U64_MAX, U64_MAX,
			      STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
			      buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));
	KUNIT_EXPECT_STREQ(test, buf + strlen(buf) - 3, "UNK");
	KUNIT_EXPECT_NULL(test, strchr(buf, ' '));

	/* the largest input that still fits in a known unit must not say UNK */
	string_get_size(1ULL << 40, 1ULL << 40, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_NULL(test, strstr(buf, "UNK"));
}

/* ---- modifier flags ------------------------------------------------ */

static void agent_test_flags(struct kunit *test)
{
	agent_check(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	agent_check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE,
		    "1.00KiB");
	agent_check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES,
		    "1.00 Ki");
	agent_check(test, 1024, 1,
		    STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		    "1.00Ki");

	agent_check(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	agent_check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE,
		    "1.00kB");
	agent_check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES,
		    "1.00 k");
	agent_check(test, 1000, 1,
		    STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		    "1.00k");

	/* no unit prefix at all */
	agent_check(test, 512, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "512B");
	agent_check(test, 512, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "512 ");
	agent_check(test, 512, 1,
		    STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		    "512");
	/* flags must not disturb the base selection */
	agent_check(test, 1024, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE,
		    "1.02kB");
	agent_check(test, 1000, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE,
		    "1000B");
}

/* ---- buffer length and truncation ---------------------------------- */

static void agent_test_truncation(struct kunit *test)
{
	char buf[AGENT_BUF_LEN];
	int ret;

	/* full output "1.00 KiB" is 8 characters */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 9);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 KiB");
	KUNIT_EXPECT_EQ(test, buf[9], 'X');

	/* one byte short: last character dropped, still terminated */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 Ki");
	KUNIT_EXPECT_EQ(test, buf[8], 'X');

	/* heavy truncation */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.0");
	KUNIT_EXPECT_EQ(test, buf[4], 'X');

	/* room only for the terminator */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_EQ(test, buf[0], '\0');
	KUNIT_EXPECT_EQ(test, buf[1], 'X');

	/* zero length: nothing written, length still reported */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_EQ(test, buf[0], 'X');

	/* zero size path is subject to the same rules */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(0, 1, STRING_UNITS_10, buf, 2);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "0");
	KUNIT_EXPECT_EQ(test, buf[2], 'X');
}

static void agent_test_return_length(struct kunit *test)
{
	char buf[AGENT_BUF_LEN];

	KUNIT_EXPECT_EQ(test, string_get_size(0, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 3);
	KUNIT_EXPECT_EQ(test, string_get_size(1, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 6);
	KUNIT_EXPECT_EQ(test, string_get_size(100, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 5);
	KUNIT_EXPECT_EQ(test, string_get_size(1000, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 7);
	KUNIT_EXPECT_EQ(test, string_get_size(1024, 1, STRING_UNITS_2, buf,
					      sizeof(buf)), 8);
	KUNIT_EXPECT_EQ(test, string_get_size(1024, 1,
					      STRING_UNITS_2 | STRING_UNITS_NO_SPACE,
					      buf, sizeof(buf)), 7);
	KUNIT_EXPECT_EQ(test, string_get_size(1024, 1,
					      STRING_UNITS_2 | STRING_UNITS_NO_BYTES,
					      buf, sizeof(buf)), 7);
	KUNIT_EXPECT_EQ(test, string_get_size(1024, 1,
					      STRING_UNITS_2 | STRING_UNITS_NO_SPACE |
					      STRING_UNITS_NO_BYTES,
					      buf, sizeof(buf)), 6);
	/* the documented 9-byte minimum buffer is enough for any known unit */
	KUNIT_EXPECT_LE(test, string_get_size(1ULL << 40, 1ULL << 40,
					      STRING_UNITS_2, buf, sizeof(buf)), 8);
	KUNIT_EXPECT_LE(test, string_get_size(U64_MAX, 4096, STRING_UNITS_10,
					      buf, sizeof(buf)), 8);
}

